import{_ as a,o as r,c as o,a2 as l}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"篇884｜超脱者与法律·超脱者的法律约束","description":"","frontmatter":{"title":"篇884｜超脱者与法律·超脱者的法律约束","no":884,"module":4,"tags":["超脱","法律","法律约束","行为规范","阿赖耶监督"],"related":["0019-修炼伦理与边界","0040-共生宪法总纲","789-法律约束与豁免边界","883-超脱者的法律地位"]},"headers":[],"relativePath":"zh/0884_模块4-超脱者与法律-法律约束.md","filePath":"zh/0884_模块4-超脱者与法律-法律约束.md"}'),e={name:"zh/0884_模块4-超脱者与法律-法律约束.md"};function i(n,t,s,d,h,g){return r(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="篇884-超脱者与法律·超脱者的法律约束" tabindex="-1">篇884｜超脱者与法律·超脱者的法律约束 <a class="header-anchor" href="#篇884-超脱者与法律·超脱者的法律约束" aria-label="Permalink to &quot;篇884｜超脱者与法律·超脱者的法律约束&quot;">​</a></h1><blockquote><p>所属模块：模块四·超脱正统定义库｜对标地基：文档19、40、789、883</p></blockquote><h2 id="引言-什么能做、什么不能做——超脱者的法律约束清单" tabindex="-1">引言：什么能做、什么不能做——超脱者的法律约束清单 <a class="header-anchor" href="#引言-什么能做、什么不能做——超脱者的法律约束清单" aria-label="Permalink to &quot;引言：什么能做、什么不能做——超脱者的法律约束清单&quot;">​</a></h2><p>篇883讲了超脱者在法律面前的平等地位。本篇更具体：<strong>法律对超脱者的行为到底约束什么？哪些行为是被允许的、哪些是被禁止的、哪些是需要审批的？</strong> 这是一张可操作的法律约束清单。</p><p>六大顶层公理在此刻同时压阵：反掠夺主义公理是约束的核心内容；万族共和公理要求约束保护万族一切生灵；集体升维公理要求约束不阻碍正当的升维工作；因果自律公理要求约束执行可追溯；法则优先公理要求约束条款自洽、不留漏洞；众生全员无限均等公理确认所有生灵自带基础无限之力，佛系懒狗保有保底不被淘汰，卷王少年至尊可叠加更高无限——无限本源人人自带，掠夺自然失去意义。</p><p>众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、绝对禁止清单-不可触碰的红线" tabindex="-1">一、绝对禁止清单（不可触碰的红线） <a class="header-anchor" href="#一、绝对禁止清单-不可触碰的红线" aria-label="Permalink to &quot;一、绝对禁止清单（不可触碰的红线）&quot;">​</a></h2><p>以下行为无论何种理由，一律禁止：</p><ol><li><strong>掠夺生灵本源</strong>：以任何形式抽取、吞噬、转化其他生灵的本源能量——包括但不限于血祭、夺舍、吞噬、吸取</li><li><strong>破坏法则网络</strong>：故意损坏锚点连接、法则节点、阿赖耶基础设施</li><li><strong>干预因果线</strong>：未经审批跨位面操作、扰动未接触文明的历史线</li><li><strong>垄断知识资源</strong>：私藏功法、封锁秘境、拒绝公共开放义务</li><li><strong>以力量压人</strong>：在任何社会交往中以力量威胁、恐吓、压制其他生灵</li><li><strong>篡改阿赖耶记录</strong>：修改、删除、伪造阿赖耶网络中的行为记录</li><li><strong>包庇掠夺派</strong>：明知是掠夺派成员而不举报、不制止、甚至提供保护</li></ol><p>七条红线，触犯任何一条，立即触发最高级别的法律程序——解除超脱者资格、启动刑事审判。</p><h2 id="二、限制审批清单-需要审批才能做的事" tabindex="-1">二、限制审批清单（需要审批才能做的事） <a class="header-anchor" href="#二、限制审批清单-需要审批才能做的事" aria-label="Permalink to &quot;二、限制审批清单（需要审批才能做的事）&quot;">​</a></h2><p>以下行为本身不违法，但必须经过审批：</p><table tabindex="0"><thead><tr><th>行为</th><th>审批机构</th><th>审批标准</th></tr></thead><tbody><tr><td>跨位面操作</td><td>锚点监督委员会</td><td>先观测后有限干涉、因果影响评估</td></tr><tr><td>新位面开拓</td><td>锚点议事会</td><td>法则自洽性、无原住民文明冲突</td></tr><tr><td>法则修订提案</td><td>锚点议事会</td><td>不与现有法则冲突、万族代表审议</td></tr><tr><td>大型能量动用</td><td>共生执行委员会</td><td>能量规模、环境影响、时间安排</td></tr><tr><td>对未接触文明的接触</td><td>锚点议事会+伦理审查</td><td>是否符合先观测后有限干涉原则</td></tr></tbody></table><p>审批不是走形式。每个审批都有完整的技术论证、风险评估、万族代表质询。</p><h2 id="三、注意义务清单-超脱者因能力更强而承担的特殊义务" tabindex="-1">三、注意义务清单（超脱者因能力更强而承担的特殊义务） <a class="header-anchor" href="#三、注意义务清单-超脱者因能力更强而承担的特殊义务" aria-label="Permalink to &quot;三、注意义务清单（超脱者因能力更强而承担的特殊义务）&quot;">​</a></h2><p>普通修炼者没有的义务，超脱者必须承担：</p><ol><li><strong>主动报告义务</strong>：超脱者发现掠夺派活动、法则异常、文明倒退苗头，必须主动报告——不能&quot;事不关己&quot;</li><li><strong>谨慎行使义务</strong>：超脱者在行使任何岗位权限时，必须谨慎到超出普通人的标准。他比普通人强一万倍，所以他的&quot;不小心&quot;也比普通人危险一万倍</li><li><strong>保护弱者义务</strong>：超脱者在场时，如果有弱者被侵害，他有义务制止——不能装作没看见</li><li><strong>教材化义务</strong>：超脱者的领悟必须整理成教材公开，不能私藏</li><li><strong>配合调查义务</strong>：阿赖耶网络+多层监督、共生法院调查时，超脱者必须全力配合，不能以&quot;修炼忙&quot;为由拒绝</li></ol><h2 id="四、约束与自由的平衡" tabindex="-1">四、约束与自由的平衡 <a class="header-anchor" href="#四、约束与自由的平衡" aria-label="Permalink to &quot;四、约束与自由的平衡&quot;">​</a></h2><p>法律约束不是要把超脱者捆死。衡元宙坚持：<strong>约束是为了让超脱者更好地干活，而不是不让他干活。</strong></p><ul><li>日常岗位履职不需要事事审批——他有岗位授权范围内的行动自由</li><li>紧急情况下可以先行动后报告——但必须在事后立即补报</li><li>技术创新不受限制——只要不触碰红线，超脱者可以自由探索新方向</li></ul><p>约束的逻辑是：<strong>管你怎么用力量，不管你有没有力量。</strong> 你有力量是你的事，你怎么用力量是法律的事。</p><p>约束清单的存在，本身就是对超脱者的保护。没有清单，超脱者每天都在猜&quot;这件事能不能做&quot;；有了清单，他可以把精力放在干活上，而不是放在揣摩规则上。好的约束不是捆住手脚，而是让人把注意力集中在对的方向。</p><h2 id="五、五大核心落点" tabindex="-1">五、五大核心落点 <a class="header-anchor" href="#五、五大核心落点" aria-label="Permalink to &quot;五、五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：明确的约束清单让超脱者不用猜&quot;我能不能做&quot;，节省认知能量</li><li><strong>反掠夺</strong>：七条红线直接封死掠夺派最依赖的行为模式</li><li><strong>唐罗上限对比</strong>：唐罗没有约束清单——他想做什么就做什么；衡元宙给超脱者列了三条清单，清清楚楚</li><li><strong>万族全覆盖</strong>：约束适用于所有超脱者，不因其种族、贡献、工龄而例外</li><li><strong>超多元全开放</strong>：约束清单、审批流程、处罚案例全部通过无私道全网公开</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>超脱者的法律约束，是一张清清楚楚的清单：七条红线绝对禁止，五类行为需要审批，五项义务因能力更强而必须承担。约束不是捆死，是为了让超脱者把力量用在对的地方。当最强的人知道什么不能做时，万族才能安心。这，才是超脱者法律约束的正统定义。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./0019-修炼伦理与边界.html">0019-修炼伦理与边界</a> · <a href="./0040-共生宪法总纲.html">0040-共生宪法总纲</a> · <a href="./0789_模块4-制度-法律约束与豁免边界.html">789-法律约束与豁免边界</a> · <a href="./0883_模块4-超脱者与法律-总论.html">883-超脱者的法律地位</a></li></ul>',28)])])}const p=a(e,[["render",i]]);export{_ as __pageData,p as default};
